/** Explicit, local-only support panel. No network, telemetry, device fingerprint or extra GL context. */
export function createExperienceDiagnostic({window:win=window,document:doc=document,reduced=()=>false}={}){
 if(new URLSearchParams(win.location?.search||'').get('galleryDiagnostic')!=='1')return{enabled:false,update(){},dispose(){}};
 const panel=doc.createElement('aside'),title=doc.createElement('strong'),note=doc.createElement('p'),output=doc.createElement('pre'),actions=doc.createElement('div'),copy=doc.createElement('button'),close=doc.createElement('button');let closed=false,state={mode:'pending',phase:'waiting',loaded:0,total:8,runtimeRevision:'—',attempt:0,elapsedMs:0,error:null,contextLost:false};
 panel.setAttribute('aria-label','Diagnóstico local da galeria');panel.style.cssText='position:fixed;z-index:2147483646;left:12px;bottom:12px;box-sizing:border-box;width:410px;max-width:calc(100vw - 24px);max-height:48vh;overflow:auto;padding:14px;border:1px solid #bc8d9d;border-radius:8px;background:#26171ff5;color:#f3eee6;box-shadow:0 8px 30px #0006;font:12px/1.45 Arial,sans-serif;letter-spacing:0;pointer-events:auto;user-select:text';
 title.textContent='Diagnóstico da galeria';title.style.cssText='display:block;font-size:14px';note.textContent='Verificação local. Nenhum dado é enviado. Envie um print deste painel.';note.style.cssText='margin:6px 0 10px';output.style.cssText='margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.45 monospace;user-select:text';actions.style.cssText='display:flex;gap:12px;margin-top:10px';
 copy.textContent='Copiar diagnóstico';close.textContent='Fechar';for(const button of[copy,close]){button.type='button';button.style.cssText='border:1px solid #bc8d9d;border-radius:4px;padding:7px 10px;background:#542a37;color:#f3eee6;font:12px Arial,sans-serif;cursor:pointer';}
 const phases={waiting:'aguardando esta seção',idle:'aguardando esta seção',runtime:'carregando renderizador',context:'criando contexto gráfico',images:'carregando fotografias',ready:'pronto',fallback:'versão leve ativa',paused:'pausado fora da área visível'};
 function draw(){const error=typeof state.error==='string'?state.error:state.error?.message;output.textContent=[`Versão: ${doc.body?.dataset?.build||'não identificada'}`,`Renderização: ${state.mode==='webgl'?'WebGL completo':state.mode==='fallback'?'versão leve (DOM)':'preparando'}`,`Etapa: ${phases[state.phase]||state.phase}`,`Fotografias: ${state.loaded??0} / ${state.total??8}`,`Runtime: Three ${state.runtimeRevision||'—'}`,`Tentativa: ${state.attempt||0} · ${(Math.max(0,Number(state.elapsedMs)||0)/1000).toFixed(1)} s`,`Movimento reduzido: ${reduced()?'sim':'não'}`,`Contexto perdido: ${state.contextLost?'sim':'não'}`,`Último descarte: ${state.lastDisposeReason||'nenhum'} · geração ${state.lastDisposeGeneration??'—'}`,`Geração atual: ${state.generation??'—'}`,`Perda registrada: ${state.contextLoss?`${state.contextLoss.lastDisposeReason||'sem descarte anterior'} · geração ${state.contextLoss.generation}`:'nenhuma'}`,`Motivo registrado: ${error||'nenhum erro registrado'}`].join('\n');}
 function dispose(){if(closed)return;closed=true;panel.remove();}
 copy.addEventListener('click',async()=>{try{if(!win.navigator?.clipboard?.writeText)throw Error('Clipboard unavailable');await win.navigator.clipboard.writeText(output.textContent);copy.textContent='Copiado';}catch{copy.textContent='Selecione o texto para copiar';}});close.addEventListener('click',dispose);
 actions.append(copy,close);panel.append(title,note,output,actions);doc.body.append(panel);draw();
 return{enabled:true,update(patch={}){if(closed)return;state={...state,...patch};draw();},dispose};
}
